const id = () => Date.now().toString(36) + Math.random().toString(36).slice(2);

function load(table) {
  try { return JSON.parse(localStorage.getItem('bwanali_' + table) || '[]'); } catch { return []; }
}
function save(table, rows) {
  localStorage.setItem('bwanali_' + table, JSON.stringify(rows));
  window.dispatchEvent(new CustomEvent('db-change', { detail: { table } }));
}

if (!localStorage.getItem('bwanali_seeded')) {
  save('stores', [{ id: 'store-1', name: 'Demo Store', subscription_status: 'trialing', trial_started_at: new Date().toISOString(), subscription_plan: 'monthly', locked: false }]);
  save('staff', [{ id: 'staff-1', store_id: 'store-1', full_name: 'Admin Demo', email: 'admin@demo.com', role: 'admin', pin_code: '1234', is_active: true }]);
  save('products', [
    { id: 'prod-1', store_id: 'store-1', name: 'Cooking Oil 2L', barcode: '111', category: 'Groceries', unit_price: 230, cost_price: 210, stock_quantity: 20, is_active: true },
    { id: 'prod-2', store_id: 'store-1', name: 'Sugar 1kg', barcode: '222', category: 'Groceries', unit_price: 38, cost_price: 30, stock_quantity: 100, is_active: true },
    { id: 'prod-3', store_id: 'store-1', name: 'Bread Loaf', barcode: '333', category: 'Bakery', unit_price: 25, cost_price: 18, stock_quantity: 50, is_active: true },
  ]);
  save('company_settings', [{ id: 'settings-1', store_id: 'store-1', company_name: 'Demo Store Ltd', local_currency: 'ZMW', receipt_footer: 'Thank you!' }]);
  save('customers', []); save('sales', []); save('sale_items', []);
  save('cash_shifts', []); save('discount_rules', []); save('returns', []);
  save('laybys', []); save('store_admins', []);
  localStorage.setItem('bwanali_seeded', '1');
}

function P(fn) {
  const promise = new Promise((resolve, reject) => {
    try { const result = fn(); resolve(result); } catch (e) { reject(e); }
  });
  promise.catch(() => {});
  return promise;
}

function queryBuilder(table) {
  const context = {
    table,
    filters: [],
    limitVal: null,
    singleMode: false,
    orderCol: null,
    orderAsc: true,
    countMode: false,
    headOnly: false,
  };

  const builder = {
    select: (cols, opts) => {
      if (opts?.count === 'exact') { context.countMode = true; if (opts.head) context.headOnly = true; }
      return builder;
    },
    eq: (col, val) => { context.filters.push({ type: 'eq', col, val }); return builder; },
    gte: (col, val) => { context.filters.push({ type: 'gte', col, val }); return builder; },
    lte: (col, val) => { context.filters.push({ type: 'lte', col, val }); return builder; },
    not: (col, val) => { context.filters.push({ type: 'not', col, val }); return builder; },
    is: (col, val) => { context.filters.push({ type: 'is', col, val }); return builder; },
    in: (col, vals) => { context.filters.push({ type: 'in', col, vals }); return builder; },
    or: (condition) => {
      // Support simple OR conditions like `column.gte.value,column.lte.value`
      const parts = condition.split(',');
      const orFilters = [];
      parts.forEach(part => {
        const [col, op, val] = part.split('.');
        if (op === 'gte') orFilters.push({ type: 'gte', col, val });
        else if (op === 'lte') orFilters.push({ type: 'lte', col, val });
        else if (op === 'eq') orFilters.push({ type: 'eq', col, val });
      });
      // Add as a single "or" filter that checks if any sub-filter matches
      context.filters.push({ type: 'or', filters: orFilters });
      return builder;
    },
    order: (col, opts) => { context.orderCol = col; context.orderAsc = opts?.ascending !== false; return builder; },
    limit: (n) => { context.limitVal = n; return builder; },
    single: () => { context.singleMode = true; return builder; },
    maybeSingle: () => { context.singleMode = true; return builder; },
    then: (resolve) => {
      return P(() => {
        let rows = load(context.table);
        rows = rows.filter(r => context.filters.every(f => {
          try {
            if (f.type === 'eq') return r[f.col] === f.val;
            if (f.type === 'gte') return new Date(r[f.col]) >= new Date(f.val);
            if (f.type === 'lte') return new Date(r[f.col]) <= new Date(f.val);
            if (f.type === 'not') return r[f.col] !== f.val;
            if (f.type === 'is') return r[f.col] === null || r[f.col] === undefined;
            if (f.type === 'in') return f.vals.includes(r[f.col]);
            if (f.type === 'or') return f.filters.some(sf => {
              if (sf.type === 'gte') return new Date(r[sf.col]) >= new Date(sf.val);
              if (sf.type === 'lte') return new Date(r[sf.col]) <= new Date(sf.val);
              return false;
            });
            return true;
          } catch { return false; }
        }));
        if (context.orderCol) rows.sort((a, b) => (a[context.orderCol] > b[context.orderCol] ? 1 : -1) * (context.orderAsc ? 1 : -1));
        if (context.limitVal !== null) rows = rows.slice(0, context.limitVal);
        const result = context.singleMode ? { data: rows[0] || null, error: null } : { data: rows, error: null };
        if (context.countMode) {
          result.count = rows.length;
          if (context.headOnly) result.data = [];
        }
        resolve(result);
      });
    },
    catch: (fn) => { return builder; },
  };
  return builder;
}

export const supabase = {
  from: (table) => ({
    select: (cols, opts) => queryBuilder(table).select(cols, opts),
    insert: (data) => {
      const arr = Array.isArray(data) ? data : [data];
      const rows = load(table);
      const newRows = arr.map(d => {
        const base = { id: id(), ...d };
        if (table === 'sales' && !base.invoice_number) base.invoice_number = '' + (rows.length + 1);
        return base;
      });
      save(table, [...rows, ...newRows]);
      const promise = P(() => ({ data: newRows, error: null }));
      promise.select = () => ({
        single: () => P(() => ({ data: newRows[0] || null, error: null })),
        then: (resolve) => resolve({ data: newRows, error: null }),
        catch: () => {},
      });
      promise.single = () => P(() => ({ data: newRows[0] || null, error: null }));
      return promise;
    },
    update: (data) => ({
      eq: (col, val) => P(() => {
        const rows = load(table);
        const updated = rows.map(r => r[col] === val ? { ...r, ...data } : r);
        save(table, updated);
        return { error: null };
      }),
      in: (col, vals) => P(() => {
        const rows = load(table);
        const updated = rows.map(r => vals.includes(r[col]) ? { ...r, ...data } : r);
        save(table, updated);
        return { error: null };
      }),
    }),
    delete: () => ({
      eq: (col, val) => P(() => {
        const rows = load(table);
        save(table, rows.filter(r => r[col] !== val));
        return { error: null };
      }),
    }),
    upsert: (data) => P(() => {
      const rows = load(table);
      (Array.isArray(data) ? data : [data]).forEach(d => {
        const idx = rows.findIndex(r => r.id === d.id);
        if (idx >= 0) rows[idx] = d;
        else rows.push({ id: id(), ...d });
      });
      save(table, rows);
      return { error: null };
    }),
  }),
  auth: {
    signInWithPassword: async ({ email, password }) => {
      const staff = load('staff');
      const user = staff.find(u => u.email === email && u.pin_code === password);
      if (!user) return { error: { message: 'Invalid credentials' } };
      localStorage.setItem('local_user', JSON.stringify(user));
      return { data: { user }, error: null };
    },
    signOut: async () => { localStorage.removeItem('local_user'); return { error: null }; },
    getSession: async () => {
      const user = JSON.parse(localStorage.getItem('local_user') || 'null');
      return { data: { session: user ? { user, access_token: 'offline', refresh_token: 'offline' } : null } };
    },
    onAuthStateChange: (cb) => {
      const user = JSON.parse(localStorage.getItem('local_user') || 'null');
      setTimeout(() => cb('SIGNED_IN', { user }), 10);
      return { data: { subscription: { unsubscribe: () => {} } } };
    },
    setSession: async () => ({ error: null }),
    signUp: async ({ email, password, options }) => {
      const staff = load('staff');
      const newUser = { id: id(), email, pin_code: password, full_name: options?.data?.full_name || 'New User', role: 'cashier', is_active: true, store_id: null };
      save('staff', [...staff, newUser]);
      return { data: { user: newUser }, error: null };
    },
  },
  storage: {
    from: () => ({
      upload: async () => P(() => ({ error: null })),
      getPublicUrl: () => ({ data: { publicUrl: '' } }),
    }),
  },
  rpc: () => P(() => ({ error: null })),
};
